<?php
 namespace OSS\Model; class BucketInfo { public function __construct($location = '', $name = '', $createDate = '') { $this->location = $location; $this->createDate = $createDate; $this->name = $name; } public function getLocation() { return $this->location; } public function getName() { return $this->name; } public function getCreateDate() { return $this->createDate; } public function getStorageClass() { return $this->storageClass; } public function getExtranetEndpoint() { return $this->extranetEndpoint; } public function getIntranetEndpoint() { return $this->intranetEndpoint; } public function getRegion() { return $this->region; } public function parseFromXmlNode($xml) { if (isset($xml->Location)) { $this->location = strval($xml->Location); } if (isset($xml->Name)) { $this->name = strval($xml->Name); } if (isset($xml->CreationDate)) { $this->createDate = strval($xml->CreationDate); } if (isset($xml->StorageClass)) { $this->storageClass = strval($xml->StorageClass); } if (isset($xml->ExtranetEndpoint)) { $this->extranetEndpoint = strval($xml->ExtranetEndpoint); } if (isset($xml->IntranetEndpoint)) { $this->intranetEndpoint = strval($xml->IntranetEndpoint); } if (isset($xml->IntranetEndpoint)) { $this->intranetEndpoint = strval($xml->IntranetEndpoint); } if (isset($xml->Region)) { $this->region = strval($xml->Region); } } private $location; private $name; private $createDate; private $storageClass; private $extranetEndpoint; private $intranetEndpoint; private $region; }